"""R2 (evidence-first rebuild) text changes relative to the R1 submission, keyed by R1 paragraph index.
Same format as r2/manuscript/spec.py. Every number is read from pgph_rebuild/05_analysis/results (no hard-coded results)."""
import json, re, sys
from pathlib import Path
import pandas as pd
RB = Path(__file__).resolve().parents[1]; ROOT = RB.parent; RES = RB / "05_analysis/results"; M = RB / "04_validated_master"
sys.path.insert(0, str(ROOT / "r2/manuscript"))
import spec as OLD
_rg = lambda r: re.sub(r'^(.*), (.*)$', r'\1 (\2)', r)
H1, H2, NB, LB, LN = "Heading 1", "Heading 2", "Normal", "List Bullet", "List Number"
ACC = "[cited 2026 Nov 19]"
EXTRA_REFS = {
 "gcc_regs": f"Gulf Health Council. Regulations of medical examination of expatriates coming to GCC States for work or residence. 6th version. Riyadh: Gulf Health Council; 2021. {ACC}. Available from: https://wafid.com/static/pdf/Regulations%20of%20Medical%20Examination%20of%20Expatriates%20Coming%20to%20GCC%20States%20for%20Work%20or%20Residence.pdf",
 "lambert2015": "Lambert SM, Walker SL. The deportation of two Ethiopian migrant workers with leprosy. Lepr Rev. 2015;86:108–11.",
}
CODE = {"HD": "Hansen’s disease", "TB": "tuberculosis", "HIV": "HIV", "SYPH": "syphilis", "STI_OTHER": "other sexually transmitted infections", "HBV": "hepatitis B",
        "HCV": "hepatitis C", "MENTAL": "mental disorders", "SUBST_DEP": "substance dependence", "DRUG_TEST": "drug testing", "ALCOHOL": "alcohol dependence",
        "MALARIA": "malaria", "FILARIASIS": "filariasis", "OTHER_NAMED": "other named conditions"}
ORIGIN = {"nationality", "origin", "origin_endemic_country", "residence_or_origin", "prior_residence", "programme_coverage", "exam_country"}
def L(x):
    x = list(x); return "" if not x else x[0] if len(x) == 1 else ", ".join(x[:-1]) + " and " + x[-1]
def W(n): return ["no", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"][n] if n <= 10 else str(n)
f2 = lambda x: f"{x:.2f}".replace("-", "−")

def load():
    return json.load(open(RES / "rebuild_numbers.json"))

def build(N=None):
    N = N or load(); T = N["N"]; c, p = N["categories"], N["pct"]; nA, nB, nD, nU = c["A"], c["B"], c["D"], c["U"]
    pos, ex, el, pt, ptl = N["documented_positive"], N["exclusion"], N["exclusion_lists"], N["post_treatment"], N["post_treatment_lists"]
    s, v, b = N["search"], N["validation"], N["burden"]; fr = N["frame"]
    sl = pd.read_csv(M / "SEARCH_LOG.csv", dtype=str); ts = pd.to_datetime(sl.timestamp_utc, errors="coerce").dropna()
    d0, d1 = ts.min().strftime("%-d %B %Y"), ts.max().strftime("%-d %B %Y")
    jm = pd.read_csv(M / "JURISDICTION_MASTER.csv", dtype=str, keep_default_na=False); lp = jm.local_pass_done.value_counts()
    rec = pd.read_csv(RB / "07_audits/HD_COUNT_RECONCILIATION.csv"); rec = rec[rec.hd_named_final]
    nm = jm.set_index("jurisdiction_id").name
    adm = [nm[j] for j in rec[~rec.criterion_types.str.contains("diagnostic")].jurisdiction_id]
    bt = sorted(((k.split(" ", 1)[1].replace(" (", ", ").replace(")", "").replace(" + ", " and "), x["unresolved"], x["n"]) for k, x in N["batch"].items()), key=lambda t: t[1] / t[2])
    hi = bt[-2:][::-1]
    fq = sorted(((k, x["named"]) for k, x in N["freq"].items() if k in CODE and k != "OTHER_NAMED" and x["named"] > 0), key=lambda t: -t[1])
    freq_txt = L(f"{CODE[k]} ({n})" for k, n in fq if k not in ("DRUG_TEST",))
    ba, bg = b["all"], b["gcc_once"]; og = {k: v for k, v in N["origin_triggers_A"].items() if set(v) & ORIGIN}; sa = N["safeguards_A"]; sf = N["safeguards"]
    S = dict(OLD.build())
    trg = pd.read_csv(M / "NATIONALITY_ORIGIN_TRIGGERS.csv", dtype=str, keep_default_na=False)
    mus = trg[(trg.jurisdiction_id == "J-MUS") & trg.notes.str.contains("leprosy-free certificate")].trigger_value.iloc[0].split(";")
    mus_hi = [("the " + x if x == "Philippines" else x) for x in mus if x in ("Brazil", "India", "Indonesia", "Bangladesh", "Ethiopia", "Nigeria", "Philippines")]
    S[0] = [("R", None, f"Hansen’s disease in work-related migration medical requirements: an evidence-first scoping review of {T} jurisdictions")]
    S[2] = [("R", None, "Short title: Hansen’s disease in work-related migration medical requirements")]
    S[11] = [("R", None, "Background\nHansen’s disease (leprosy) is curable with multidrug therapy (MDT), yet some jurisdictions still name it in medical requirements for migrant workers. Their consequences and treatment-status rules have not been systematically documented.")]
    S[12] = [("R", None, "Objectives\nTo identify jurisdictions naming Hansen’s disease in official migration-related medical requirements for work, and to characterise stated consequences, treatment-status provisions, safeguards and origin-based applicability.")]
    S[13] = [("R", None, f"Methods\nScoping review following PRISMA-ScR of {T} jurisdictions. Official sources were searched in English and local languages ({s['queries']:,} logged queries), {s['sources_saved']} source documents were archived with checksums, and evidence was extracted at the provision level ({s['evidence_rows']} evidence rows). An independent second pass re-examined {v['items']} classification items ({v['agree']} agreed). Insufficient evidence was recorded as unresolved, not as absence.")]
    S[14] = [("R", None, f"Results\nDisease-specific screening was documented in {pos} jurisdictions, its absence in {nD}, and requirements remained unresolved in {nU} ({p['U']}%). Hansen’s disease was named in an applicable official requirement in {nA} jurisdictions, representing {N['hd_mechanisms']} distinct mechanisms because the six Gulf Cooperation Council states share one programme. Located sources stated visa refusal or inadmissibility in {ex['visa_refusal_inadmissibility']}, entry denial in {ex['entry_denial']}, removal in {ex['removal_deportation']} and denial or revocation of work authorisation in {ex['work_authorisation_denial_or_revocation']}. Only Brunei explicitly excluded persons with a treatment history; the United States, Taiwan and Mauritius had conditional or treatment-based provisions, and {pt['no_treatment_distinction_named_condition']} jurisdictions named the disease without any treatment distinction. Case-level evidence of removal was located for one jurisdiction (Kuwait; two workers on treatment). Origin-based applicability operated through exemption lists, nationality rules and programme country coverage.")]
    S[15] = [("R", None, f"Conclusions\nHansen’s disease remains named in work-related migration medical requirements in at least {nA} jurisdictions, mostly without distinguishing infectious from treated disease. Because {nU} jurisdictions could not be resolved, counts of documented provisions are minimum counts for the 199 jurisdictions. These provisions should be reviewed so that, at minimum, persons receiving or having completed MDT are not excluded.")]
    S[27] = [("R", None, "(1) In how many jurisdictions can disease-specific medical requirements for work-related migration be documented, and for how many does the evidence remain unresolved?")]
    S[28] = [("R", None, "(2) Which jurisdictions name Hansen’s disease in an applicable official requirement, through which instruments, and with which stated consequences?")]
    S[29] = [("R", None, "(3) Do these provisions distinguish infectious from treated disease, provide waiver, appeal or re-examination, and apply differently by country of origin?")]
    S[30] = [("R", None, "(4) Which other conditions are named in documented requirements, and is the presence of Hansen’s disease provisions associated with national leprosy burden?")]
    S[31] = []
    S[35] = [("R", None, "This scoping review followed the PRISMA Extension for Scoping Reviews (PRISMA-ScR) [@tricco2018] and the framework of Arksey and O’Malley [@arksey2005;@levac2010]. The protocol was not registered. For this revision the evidence base was rebuilt from primary sources under a protocol in which eligibility, endpoints, search passes and the data schema were fixed before data collection; the protocol is archived with the data.")]
    S[37] = [("R", None, f"Population: {T} jurisdictions: the {fr.get('UN member State', 0)} UN Member States, the Holy See and the State of Palestine, and Taiwan, Kosovo, Hong Kong SAR and Macao SAR, which operate separate immigration regimes. The US Virgin Islands were merged with the United States because US federal immigration law applies.")]
    S[38] = [("R", None, "Concept: Official migration-related medical requirements for work (work visas, work permits, employment passes and pre-departure or post-arrival medical examinations of migrant workers), including the conditions named, the criterion type, the stated consequence, treatment-status rules, safeguards and origin-based applicability.")]
    S[39] = [("R", None, "Context: Laws, regulations, official medical examination forms, panel-physician instructions and official administrative guidance applicable at the time of search. Peer-reviewed case reports were used only as evidence of decisions in individual cases.")]
    S[40] = [("R", None, "Types of evidence sources: Sources were ranked by a pre-specified hierarchy: legislation or regulation; official forms and instructions; official guidance or web pages; archived official pages; peer-reviewed or other secondary sources. Search-engine snippets, AI-generated summaries and unverified historical classifications were not accepted as evidence for any classification.")]
    st = s["stage"]
    S[42] = [("R", None, f"Searches were conducted {('on ' + d0) if d0 == d1 else ('between ' + d0 + ' and ' + d1)} in four pre-specified passes for every jurisdiction: (P1) English-language searches of official immigration, labour and health sources; (P2) searches in official or local languages; (P3) applicability and chronology checks; and (P4) targeted resolution of ambiguous wording. In total {s['queries']:,} queries were logged (P1 {st.get('P1_english', 0)}, P2 {st.get('P2_local', 0)}, P3 {st.get('P3_applicability', 0)}, P4 {st.get('P4_ambiguity', 0)}) and {s['opened_full_text']} full-text openings were recorded. Sources included:")]
    S[43] = [("R", None, "Official immigration, labour and health ministry websites and online forms")]
    S[44] = [("R", None, "National legislation databases and official gazettes, in English and local languages")]
    S[46] = []
    S[48] = [("R", None, "PubMed and Google Scholar, for case reports and peer-reviewed analyses of migrant medical screening")]
    S[49] = [("R", None, "Grey literature (law-firm and panel-physician guides), used only as leads to official sources")]
    S[50] = [("R", None, "Queries combined jurisdiction names with terms for work visas or permits, medical examination and named conditions, including leprosy or Hansen’s disease and their local-language equivalents. Full query strings are archived in the search log.")]
    S[51] = [("R", None, f"Local-language passes were completed for {int(lp.get('yes', 0))} jurisdictions; for the remaining {int(len(jm) - lp.get('yes', 0))}, English is an official language and the English pass served as the local-language pass. Translations were machine-assisted, and the original wording was retained with each extracted provision.")]
    S[53] = [("R", None, "Evidence collection was organised in nine regional batches. For each jurisdiction the work-related medical pathway or pathways were identified and every relevant provision was recorded as a separate evidence row linked to an archived source. Disease-specific screening was classified as documented only if at least one applicable source named a specific condition; documented absence required an official source stating that no disease-specific examination applies. All other jurisdictions were recorded as unresolved.")]
    S[55] = [("R", None, "For each evidence row we recorded the source, provision locator, original and English wording, condition, criterion type (diagnostic, administrative test or behavioural), whether the condition was explicitly named, operative effect, authority level, effective dates, treatment-status rule, safeguards, origin-based triggers, evidence tier, confidence and provenance. Provisions that were historical, repealed or not part of a medical admission criterion (for example, a domicile clause referring to leprosy hospitals) were excluded from counts by documented adjudication (S2 Appendix)."),
             ("+", H2, "2.6 Independent Verification"),
             ("+", NB, f"A second review pass, run by a separate AI agent session, re-examined {v['items']} classification items, including all jurisdictions naming Hansen’s disease, a seeded random sample of other jurisdictions and all jurisdictions whose classification differed from the original submission, against the archived sources. Disagreements were resolved by reference to the original-language source. Targeted legal checks were then made of the GCC regulation, the Thai-language provision and the current validity of the Guyanese and Liberian statutes.")]
    S[56] = [("R", None, "2.7 Synthesis of Results")]
    S[57] = [("R", None, f"Jurisdictions were assigned to mutually exclusive categories: A, Hansen’s disease explicitly named in an applicable official migration-related medical requirement; B, disease-specific screening documented but Hansen’s disease not established as named; D, documented absence of disease-specific screening; U, unresolved. Naming a disease was recorded separately from its consequences: examination required, unfit certificate possible, visa refusal or inadmissibility, entry denial, removal, denial or revocation of work authorisation, exclusion based on treatment history, and documented actual refusal. A consequence, waiver or appeal was recorded only when stated in a located source, and its absence was not interpreted as absence of the provision. Treatment status was summarised per jurisdiction by the most specific pathway rule. Disease frequencies are counts of jurisdictions among the {pos} with documented disease-specific screening; they are lower bounds for the full frame, not global rankings. All numbers in the text, tables and figures are generated by code from the validated dataset."),
             ("+", H2, "2.8 Comparison with National Leprosy Burden"),
             ("+", NB, f"For each jurisdiction we linked the most recent WHO new case detection rate per 1,000,000 population for {b['years'][0]}–{b['years'][1]} (indicator NTD_LEPR2) [@who_gho]. Category A was compared with categories B and D using the Mann–Whitney U test, the rank-biserial correlation and a bootstrap 95% confidence interval for the difference in medians (5,000 resamples), with a sensitivity analysis counting the GCC states once. Unresolved jurisdictions were excluded from this comparison.")]
    S[61] = [("R", None, f"All {T} jurisdictions were searched. Of {s['sources']} registered sources, {s['sources_saved']} were archived locally with SHA-256 checksums; {s['sources_english']} were in English and {s['sources_other']} in other languages. We extracted {s['evidence_rows']} evidence rows ({s['criterion'].get('diagnostic', 0)} diagnostic, {s['criterion'].get('administrative_test', 0)} administrative-test and {s['criterion'].get('behavioral', 0)} behavioural criteria). Evidence sufficient for classification was obtained for {N['sufficient']} jurisdictions, and {nU} ({p['U']}%) remained unresolved (Figure 1).")]
    S[62] = [("R", None, f"Information availability differed by region (Figure 2). The proportion of jurisdictions left unresolved was highest in {hi[0][0]} ({hi[0][1]} of {hi[0][2]}) and {hi[1][0]} ({hi[1][1]} of {hi[1][2]}), and lowest in {bt[0][0]} ({bt[0][1]} of {bt[0][2]}).")]
    dis = v["disagreements"]
    S[66] = [("R", None, f"The independent verification pass agreed with the first pass on {v['agree']} of {v['items']} items. The {W(len(dis))} disagreement concerned Taiwan’s origin-based rule and was resolved in favour of the verification value on the basis of the original-language source. The targeted checks confirmed the listing of leprosy in the 2021 GCC regulation, the Thai-language wording (from a consolidated text; the official gazette copy could not be retrieved) and the Guyanese provision in the 2012 official revised edition; the current validity of the Liberian provision remained unconfirmed. No classification changed as a result of these checks.")]
    S[70] = [("R", None, "The geographic distribution of the categories is shown in Figure 3, and unresolved jurisdictions are listed in S4 Appendix.")]
    S[75] = [("R", None, f"The {T} jurisdictions were categorised as follows:")]
    S[76] = [("R", None, f"Category A: Hansen’s disease named in an applicable official requirement — {nA} jurisdictions ({p['A']}%)")]
    S[77] = [("R", None, f"Category B: disease-specific screening documented, Hansen’s disease not established as named — {nB} jurisdictions ({p['B']}%)")]
    S[78] = [("R", None, f"Category D: documented absence of disease-specific screening — {nD} jurisdictions ({p['D']}%)")]
    S[79] = [("R", None, f"Category U: unresolved — {nU} jurisdictions ({p['U']}%)"),
             ("+", NB, f"Disease-specific screening was therefore documented in {pos} jurisdictions ({N['documented_positive_pct']}% of the frame). Documented absence was confirmed for {L(N['absence_names'])}. The original submission reported 58 jurisdictions with disease-specific screening, 20 naming Hansen’s disease and 52 without disease-specific requirements; these figures could not be reproduced from any retained dataset and have been replaced (Section 4.6).")]
    S[80] = []
    S[84] = [("R", None, "3.3 Jurisdictions Naming Hansen’s Disease")]
    S[85] = [("R", None, f"Hansen’s disease was named in an applicable official requirement in {nA} jurisdictions: {L(N['hd_named_names'])} (Table 1; Figure 4). Because the six GCC states apply one regional programme, these represent {N['hd_mechanisms']} distinct mechanisms. In {L(adm)} the disease appears in an examination instruction or self-declaration rather than as a stated ground of unfitness; under the pre-specified definition these jurisdictions are counted as naming the disease, and their consequences are reported separately.")]
    S[86] = [("R", None, "Table 1: Jurisdictions naming Hansen’s disease in an applicable official migration-related medical requirement")]
    S[87] = [("R", None, "Consequences, treatment-status rules, safeguards and origin-based rules are those stated in located sources; a dash does not mean that no such provision exists. Sources, retrieval dates and checksums are listed in S5 Appendix.")]
    lc, ll = N["legal_counts"], N["legal_lists"]; GCCN = {"UAE", "Bahrain", "Kuwait", "Oman", "Qatar", "Saudi Arabia"}
    def cq(k, label):
        c = lc[k]; lst = ll[k]["D"] + ll[k]["L"]
        return f"{label} in {c['documented']} ({c['direct']} directly{', ' + str(c['linked']) + ' through a linked rule' if c['linked'] else ''}; {L(lst)})"
    unk = sorted({j for k in ll for j in ll[k]["U"]})
    S[88] = [("R", None, f"Stated consequences. Each consequence was coded separately at the level of the provision. It was counted when an operative provision attached it to Hansen’s disease, by name or by an incorporated disease list (direct), or when one located source made the disease a ground of unfitness and a second located source attached the consequence to that unfitness (linked). Of the {nA} jurisdictions, located sources required a medical examination in {ex['medical_exam_required']}. They documented {cq('unfit', 'an unfit or not-cleared result')}; {cq('visa_permit_refusal_inadmissibility', 'visa or residence-permit refusal or inadmissibility')}; {cq('entry_denial', 'entry denial')}; {cq('removal_deportation', 'removal, deportation or repatriation')}; and {cq('work_authorisation_denial_revocation', 'denial or revocation of work authorisation')}. These counts overlap and cannot be added. For {L(unk)}, only generic infectious-disease or medical-fitness provisions were located for at least one consequence; these were not counted. For the six GCC states the regional regulation makes leprosy a ground of unfitness, but a national provision attaching visa or residence refusal to that finding was located only for {L([g for g in ll['visa_permit_refusal_inadmissibility']['D'] + ll['visa_permit_refusal_inadmissibility']['L'] if g in GCCN])}. In Zimbabwe, the regulation that lists leprosy refers to section 14(1)(e) of the Immigration Act, whereas the Act places prescribed diseases in section 14(1)(d); because this discrepancy could not be resolved, Zimbabwe’s consequences were not counted. Naming a disease in a requirement therefore did not by itself establish refusal."),
             ("+", NB, f"Safeguards. Among category A jurisdictions, an explicit waiver was located for {L(sa['waiver'])}, an appeal or review procedure for {L(sa['appeal_review'])} and re-examination for {L(sa['retest'])}. Across all jurisdictions and conditions, waivers were located in {sf['waiver']}, appeal or review in {sf['appeal_review']} and re-examination in {sf['retest']}."),
             ("+", NB, f"Documented decisions. Case-level evidence of an adverse decision was located for {W(len(N['denials']['jurisdictions']))} jurisdiction: a published clinical report describes the removal from Kuwait of two Ethiopian migrant workers diagnosed with Hansen’s disease, who completed MDT after returning to Ethiopia [@lambert2015]. Both had been diagnosed and had started treatment in Kuwait; the report does not establish that either had completed MDT or was non-infectious before removal. No case-level evidence of refusal of a person who had completed MDT was located.")]
    S[90] = [("R", None, "3.4 The GCC/WAFID Programme")]
    S[91] = [("R", None, "The six GCC states apply a common medical examination of expatriates administered by the Gulf Health Council through the WAFID programme [@wafid]. The Regulations of Medical Examination of Expatriates Coming to GCC States for Work or Residence (sixth version, 2021) list leprosy among the infectious ‘medical unfitness cases’ without a treatment-status qualifier, whereas the tuberculosis criterion explicitly covers active or past disease [@gcc_regs]. The examination is performed by accredited centres in programme countries before the visa is issued and is repeated after arrival; the regulation sanctions centres that certify as fit an expatriate later found unfit, with a two-month window for leprosy. The Gulf Health Council states that the list was last updated in October 2023; the updated text was not located.")]
    S[92] = [("R", None, "3.5 Treatment Status")]
    S[93] = [("R", None, f"Brunei was the only jurisdiction whose located requirement explicitly excluded persons with a past or treated history of Hansen’s disease; this rule appears in the October 2016 version of the Ministry of Health’s foreign-worker medical report, whose public copy was located on an employer’s website, and its current use could not be confirmed. Three jurisdictions had conditional or treatment-based provisions: the United States, where only infectious Hansen’s disease is a communicable disease of public health significance and a waiver is available [@cfr42;@cdcti]; Taiwan, which provides a treatment pathway and an origin-based exemption list [@tw_regs;@tw_exempt]; and Mauritius. In {pt['no_treatment_distinction_named_condition']} jurisdictions the disease was named without any identified treatment distinction, and in {W(pt.get('cannot_determine', 0))} ({L(ptl.get('cannot_determine', []))}) the wording did not allow a determination. The absence of an explicit exemption does not show that previously treated persons are excluded; it means that the outcome for them depends on unpublished examiner practice."),
             ("+", H2, "3.6 Applicability by Country of Origin"),
             ("+", NB, f"Rules linking applicability to nationality, origin, prior residence or the country of examination were located for {len(og)} of the {nA} category A jurisdictions ({L(sorted(og))}; Table 1). Mauritius requires a leprosy-free certificate, before and on arrival, only from nationals of {len(mus)} listed countries, including {L(mus_hi)}; its 2016 version applied this requirement to Indian nationals only. Taiwan exempts skilled workers from a published list of countries and areas from the Hansen’s disease examination [@tw_exempt]; Maldives applies pre-departure leprosy screening with reference to applicants from endemic countries; and the GCC examination is required in the programme countries where accredited centres operate. No located provision prohibited the entry of nationals of particular countries as such, but these rules mean that Hansen’s disease screening applies to applicants from several high-endemic countries, including India, Indonesia and Brazil, while applicants from many low-endemic countries are exempt or not covered.")]
    for i in range(94, 102): S[i] = []
    S[105] = [("R", None, "3.7 National Leprosy Burden")]
    S[106] = [("R", None, f"WHO new case detection rates were available for {b['coverage']} of {T} jurisdictions (Figure 5). The median rate was {f2(ba['median_A'])} per 1,000,000 in category A (n = {ba['n_A']}; {L(ba['A_missing'])} not covered) and {f2(ba['median_other'])} in categories B and D (n = {ba['n_other']}); the difference in medians was {f2(ba['diff'])} (bootstrap 95% CI {f2(ba['ci'][0])} to {f2(ba['ci'][1])}; Mann–Whitney p = {ba['p']}; rank-biserial r = {f2(ba['rank_biserial'])}). Counting the GCC states once gave a difference of {f2(bg['diff'])} (95% CI {f2(bg['ci'][0])} to {f2(bg['ci'][1])}; p = {bg['p']}). Because {nU} jurisdictions were unresolved and excluded, this association is descriptive and may reflect differences in information availability between jurisdictions.")]
    S[110] = [("R", None, "3.8 Other Conditions Named in Documented Requirements")]
    S[111] = [("R", None, f"Among the {pos} jurisdictions with documented disease-specific screening, the conditions most often named were {freq_txt}; drug testing was named in {N['freq']['DRUG_TEST']['named']} (Table 2; Figure 6). Mental disorders, substance dependence and drug testing are reported as separate variables. These are minimum counts: they exclude the {nU} unresolved jurisdictions and cannot be read as a global ranking. The frequencies in the original submission (for example, tuberculosis in 55 jurisdictions and Hansen’s disease as the fifth most commonly screened condition) could not be reproduced and have been withdrawn.")]
    S[112] = [("R", None, f"Table 2: Conditions named in documented disease-specific requirements (n = {pos} jurisdictions; lower bounds for the {T}-jurisdiction frame)")]
    S[114] = []; S[115] = []
    S[121] = [("R", None, f"Rebuilding the evidence base from archived primary sources showed that Hansen’s disease is named in work-related migration medical requirements in at least {nA} of {T} jurisdictions, through {N['hd_mechanisms']} mechanisms. Naming the disease was not the same as excluding people with it: stated consequences ranged from an examination item without a stated consequence to inadmissibility, removal or loss of work authorisation, and only one jurisdiction explicitly excluded people with a treatment history. The main uncertainty lies in the {nU} unresolved jurisdictions, concentrated in {hi[0][0]} and {hi[1][0]}, where requirements appear to be communicated to panel physicians or recruitment intermediaries rather than published.")]
    S[124] = [("R", None, f"Against this background, {pt['no_treatment_distinction_named_condition']} of the {nA} jurisdictions name the disease without distinguishing active from treated disease, and the GCC regulation lists leprosy as an unfitness condition without qualification. Such wording does not by itself show that treated persons are refused, but it leaves the decision to examining physicians without a published standard.")]
    S[124].append(("+", NB, f"National burden. Category A jurisdictions had higher national leprosy detection rates than documented jurisdictions that did not name the disease (Section 3.7). This contradicts the statement in the original submission that no correlation exists, which was not based on a calculation. The comparison excludes the {nU} unresolved jurisdictions, and a higher domestic burden does not make examination of incoming workers an effective means of control; the association therefore does not by itself justify these provisions."))
    S[130] = [("R", None, "Japan’s approach provides an instructive comparison. Japan enacted its Leprosy Prevention Law in 1953, mandating the isolation of persons with Hansen’s disease; the law was abolished in 1996, and in 2001 the Kumamoto District Court ruled that the prolonged enforcement of isolation violated constitutional rights [@kumamoto]. In this review, Japan’s located work-related medical requirements did not name Hansen’s disease (category B). Japan therefore illustrates that a country with a history of compulsory segregation can operate disease-specific migration medical requirements without naming Hansen’s disease, although this observation is limited to located sources.")]
    S[132] = [("R", None, "The retention of Hansen’s disease in migration medical requirements is difficult to reconcile with several international instruments:")]
